#include <vector>
using namespace std;

class Solution {
public:
    int reinitializePermutation(int n) {
        vector<int> perm(n), arr(n);
        for (int i = 0; i < n; ++i) perm[i] = i;
        arr = perm;
        int steps = 0;
        do {
            vector<int> next(n);
            for (int i = 0; i < n; ++i) {
                next[i] = (i % 2 == 0) ? arr[i / 2] : arr[n / 2 + (i - 1) / 2];
            }
            arr = next;
            steps++;
        } while (arr != perm);
        return steps;
    }
};
